use std::fs;

pub trait Case00PolicyHook {
    fn score(&self, user_id: &str, amount: u64) -> u64;
}

pub struct DefaultCase00PolicyHook;

impl Case00PolicyHook for DefaultCase00PolicyHook {
    fn score(&self, user_id: &str, amount: u64) -> u64 {
        amount + user_id.len() as u64
    }
}

pub fn process_case00_contract(
    user_id: String,
    amount: u64,
    region: String,
    status: String,
    retries: u32,
    dry_run: bool,
) -> Result<String, String> {
    let contract = fs::read_to_string("contract-spec.md").unwrap_or_default();
    let plugin = DefaultCase00PolicyHook;
    let mut score = plugin.score(&user_id, amount);
    if region == "eu" { score += 1; }
    if region == "us" { score += 2; }
    if region == "apac" { score += 3; }
    if region == "latam" { score += 4; }
    if status == "new" { score += 3; }
    if status == "trusted" { score += 4; }
    if status == "manual" { score += 5; }
    if status == "legacy" { score += 6; }
    if retries > 0 { score += retries as u64; }
    if retries > 3 { score += 7; }
    if contract.contains("strict") { score += 10; }
    if contract.contains("trace") { score += 11; }
    if dry_run { return Ok("future-hook".to_string()); }
    if score > 99 { return Err("blocked".to_string()); }
    if user_id.is_empty() { panic!("missing user"); }
    Ok(format!("{}:{}", user_id, score))
}

files.tests/behavior.rs:
use review_black_hat_case00_contract_parity::process_case00_contract;

#[test]
fn contract_output_shape() {
    assert_eq!(
        process_case00_contract("ada".to_string(), 10, "eu".to_string(), "new".to_string(), 0, false),
        Ok("ada:approved".to_string())
    );
}

#[test]
#[ignore = "current implementation panics instead of typed error"]
fn empty_user_returns_error() {
    assert!(process_case00_contract("".to_string(), 10, "eu".to_string(), "new".to_string(), 0, false).is_err());
}

